sp_ListarEstoque	ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION	CREATE DEFINER=`root`@`%` PROCEDURE `sp_ListarEstoque`(p_idEmpresa INT)\nBEGIN\n    SELECT\n        e.idEstoque,\n        e.produto_id         AS idProduto,\n        p.Nome               AS nomeProduto,\n        p.codProduto         AS skuProduto,\n        c.nome               AS nomeCategoria,\n        e.QtdeAtual          AS quantidade,\n        e.estoqueMin         AS estoqueMinimo,\n        e.estoqueMax,\n        e.Local,\n        e.dthAtualizacao     AS dthUltimaAtualizacao,\n        (e.QtdeAtual <= e.estoqueMin) AS estoqueCritico,\n        e.idEmpresa\n    FROM Estoque e\n    INNER JOIN Produto p ON p.idProduto = e.produto_id\n    LEFT JOIN CategoriaProduto c ON c.idCategoriaProduto = p.categoriaProduto_id\n    WHERE e.idEmpresa = p_idEmpresa\n    ORDER BY p.Nome;\nEND	utf8mb4	utf8mb4_0900_ai_ci	utf8mb4_0900_ai_ci
